CREATE TEMPORARY VIEW traffic_data_raw_${grass_region_without_quote} AS
SELECT
     if(operation='order','order','others') as operation
    ,is_item_card
    ,user_id
    ,reporting_business_line
    ,reporting_module
    ,reporting_object
    ,source1_reporting_business_line
    ,source1_reporting_module
    ,source1_reporting_object
    ,source2_reporting_business_line
    ,source2_reporting_module
    ,source2_reporting_object
    ,sum(imp_cnt)        as imp_cnt
    ,sum(order_cnt)      as order_cnt
    ,sum(gmv)            as gmv
FROM srdi_mart.dwm_sr_data_warehouse_tc_ab_all_cards
WHERE grass_region IN (${grass_region}) AND local_date = ${local_date}
and operation in ('order','omni_impression')
group by
     if(operation='order','order','others')
    ,is_item_card
    ,user_id
    ,reporting_business_line
    ,reporting_module
    ,reporting_object
    ,source1_reporting_business_line
    ,source1_reporting_module
    ,source1_reporting_object
    ,source2_reporting_business_line
    ,source2_reporting_module
    ,source2_reporting_object
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW  sr_data_raw_step1_${grass_region_without_quote} AS
select
     operation
    ,is_item_card
    ,user_id
    ,if(
       (reporting_business_line in ('Homepage') and reporting_module in ('Daily Discover'))
       or
       (reporting_business_line in ('Rcmd') and reporting_module in ('User Scenario'))
       ,'RCMD',''
     ) as mapping_general
    ,if(
       (source1_reporting_business_line in ('Homepage') and source1_reporting_module in ('Daily Discover'))
       or
       (source1_reporting_business_line in ('Rcmd') and source1_reporting_module in ('User Scenario'))
       ,'RCMD',''
     ) as source1_mapping_general
    ,if(
       (source2_reporting_business_line in ('Homepage') and source2_reporting_module in ('Daily Discover'))
       or
       (source2_reporting_business_line in ('Rcmd') and source2_reporting_module in ('User Scenario'))
       ,'RCMD',''
     ) as source2_mapping_general


    ,imp_cnt
    ,order_cnt
    ,gmv
from traffic_data_raw_${grass_region_without_quote}
where ( -- to reduce data size
       (reporting_business_line in ('Homepage') and reporting_module in ('Daily Discover'))
       or
       (reporting_business_line in ('Rcmd') and reporting_module in ('User Scenario'))
    or
       (source1_reporting_business_line in ('Homepage') and source1_reporting_module in ('Daily Discover'))
       or
       (source1_reporting_business_line in ('Rcmd') and source1_reporting_module in ('User Scenario'))
    or
       (source2_reporting_business_line in ('Homepage') and source2_reporting_module in ('Daily Discover'))
       or
       (source2_reporting_business_line in ('Rcmd') and source2_reporting_module in ('User Scenario'))
   )
;
--sql_divide_splitter--

create temporary view  sr_data_raw_step2_${grass_region_without_quote}
as
select  is_item_card	-- include order log item_card and imp&click all_card
        ,user_id
        ,mapping_general
        ,imp_cnt
        ,order_cnt
        ,gmv
from    sr_data_raw_step1_${grass_region_without_quote}
where   mapping_general = 'RCMD'
union all
select  'false' as is_item_card	-- copy order log from source1
        ,user_id
        ,source1_mapping_general
        ,imp_cnt
        ,order_cnt
        ,gmv
from    sr_data_raw_step1_${grass_region_without_quote}
where   source1_mapping_general = 'RCMD'
  and   operation = 'order'
  and   source1_mapping_general != mapping_general	--to guarantee order not copy double,and so the only non_item_card is not right,but no body only need this
union all
select  'false' as is_item_card	-- copy order log from source2
        ,user_id
        ,source2_mapping_general
        ,imp_cnt
        ,order_cnt
        ,gmv
from    sr_data_raw_step1_${grass_region_without_quote}
where   source2_mapping_general = 'RCMD'
  and   operation = 'order'
  and   source2_mapping_general != mapping_general
  and   source2_mapping_general != source1_mapping_general	--to guarantee order not copy double
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW user_exp_${grass_region_without_quote} as
SELECT
     user_id
    ,case
       when exp_group_id in (627728,640343,655654,655641,662593) then 'T1'
       when exp_group_id in (378802) then 'C1'
     end as exp_tag
FROM srdi_mart.dim_sr_data_warehouse_abtest_user_group
WHERE grass_region in (${grass_region}) AND local_date = ${local_date} AND is_assignment_log = 1 -- 后续统一使用assignment log join获取实验信息
and (
        (${grass_region} = 'ID' and exp_group_id in (378802,627728))
     or (${grass_region} = 'VN' and exp_group_id in (378802,640343))
     or (${grass_region} = 'PH' and exp_group_id in (378802,655654))
     or (${grass_region} = 'TH' and exp_group_id in (378802,655641))
     or (${grass_region} = 'MY' and exp_group_id in (378802,662593))
    )-- 用来打上实验信息
group by
     user_id
    ,exp_group_id
;
--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.ads_sr_data_warehouse_ni_boost_exp_performance_1d PARTITION (grass_region = ${grass_region}, local_date = ${local_date})
SELECT
     exp_tag
    ,count(distinct if(imp_cnt>0,a.user_id,null)) as imp_uv
    ,sum(order_cnt) as order_cnt
    ,sum(gmv)       as gmv
FROM sr_data_raw_step2_${grass_region_without_quote} a
inner join user_exp_${grass_region_without_quote} b on a.user_id=b.user_id
group by exp_tag
;
